std::string file_stem(const std::wstring& path)
{
    const std::wstring name = path.substr(path.find_last_of(L"/\\") + 1);
    const size_t       dot  = name.find_last_of(L'.');
    return utf8(dot == std::wstring::npos ? name : name.substr(0, dot));
