bool set_printer_access_code(const std::string& dev_id, const std::string& code, wxString& error)
{
    // ConnectPrinterDialog::on_button_confirm's rule and its one call.
    const bool valid = std::all_of(code.begin(), code.end(), [](char c) {
        return ('0' <= c && c <= '9') || ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z');
    });
    if (!valid) {
        error = _L("Invalid input.");
        return false;
    }
    DeviceManager* devices = wxGetApp().getDeviceManager();
    MachineObject* machine = devices ? devices->get_my_machine(dev_id) : nullptr;
    if (!machine) {
        error = _L("This printer is no longer on your network.");
        return false;
    }
    machine->set_user_access_code(code);
    return true;
}

bool select_bed_type(Plater& plater, int bed_type_value)
{
    const std::vector<BedType>& supported = plater.sidebar().get_cur_combox_bed_types();
    const auto found = std::find(supported.begin(), supported.end(), BedType(bed_type_value));
    if (found == supported.end())
        return false;
    // set_bed_type_accord_combox selects *and notifies*, so Orca's own
    // on_select_bed_type runs: it owns the project-config write, the
    // app-config record, the invalidation of every plate still on the default
    // bed, and the re-render. None of that is repeated here.
    //
    // Ownership note: a bed type is machine state to the person and project
    // state to Orca. The chip presents it under the printer because that is
    // where the person looks for it; the value still lives in the project.
    plater.sidebar().set_bed_type_accord_combox(BedType(bed_type_value));
    return true;
}

void open_settings_tab(Preset::Type type)
{
    Tab* tab = wxGetApp().get_tab(type);
    if (tab == nullptr)
        return;
    // PlaterPresetComboBox::switch_to_tab: the Tab activates its own page and
    // ParamsPanel, including clearing the previous page.
{
    // A named printer is monitored through the device it stands for.
    std::string device_id = strip(printer_id, kDevicePrefix).value_or(std::string());
    if (const auto name = strip(printer_id, kNamedPrefix))
        for (const Printers::NamedPrinter& named : Printers::named_printers())
            if (named.name == *name)
                device_id = named.device_id;
    if (device_id.empty())
        return; // the card changed under the click; the refreshed rail says so
    // Upstream's own path to the Monitor, as the device popup and the
    // multi-machine page use. Selecting the tab and the machine by hand
    // instead left Home on screen: jump_to_monitor also guards on the Monitor
    // panel existing and selects the machine inside it. Upstream may still
    // decline the switch -- it vetoes the Monitor tab when the network plugin
    // is missing -- and that refusal is upstream's to make.
    m_frame.jump_to_monitor(device_id);
}

void OrcaHomeBackend::add_printer()
{
    // The conversation replaces the printers column in place; the shell draws
    // it and owns the session.
    if (m_open_conversation)
        m_open_conversation({});
}

std::string OrcaHomeBackend::open_printer_settings(const std::string& printer_id)
{
    const auto name = strip(printer_id, kNamedPrefix);
    if (!name)
        return gone();
    // "Printer settings…" opens that printer's own conversation, where "Set
    // it up myself" still leads to OrcaSlicer's settings window.
    if (m_open_conversation)
        m_open_conversation(*name);
    return {};
}

