                if (tap.note) extra.note = tap.note;
                printerAction(action, id, extra);
              }}
              answeredState={false}
              onRetry={(messageId) => client.send('retry_message', { messageId })}
              onToolDecision={sendToolDecision}
              onToolCancel={sendToolCancel}
            />
          )}
          {!notConfigured && session && (
            <>
              {session.accessCode && <PrinterAccessCode value={accessCode} onChange={setAccessCode} />}
              <PrinterChipRow
                canAdd={session.canAdd}
                disabled={busy}
                onAdd={() =>
                  printerAction('add', '', session.accessCode && accessCode ? { accessCode, note: ACCESS_CODE_NOTE } : {})
                }
                onReject={() => printerAction('reject', '', { note: rejectedNote(session.facts.printer.name) })}
              />
            </>
          )}
          {!notConfigured && (
            <Composer
              disabled={unavailable}
              disabledReason={unavailable ? 'The Agent is not available' : undefined}
              placeholder={session ? placeholder(session) : undefined}
              photoButton
              streaming={streaming}
              attachments={stagedAttachments}
              onSend={(text) => {
                setPrinterDraftText('');
                sendMessage(text);
              }}
              onStop={() => {
                if (state.streamingMessageId) client.send('stop_generation', { messageId: state.streamingMessageId });
              }}
              onAttachFiles={attachFiles}
              onRemoveAttachment={removeAttachment}
              onDraftChange={setPrinterDraftText}
            />
          )}
        </div>
      </div>
    );
  }
export interface PrinterSessionPayload {
  mode: 'add' | 'change';
  facts: PrinterFacts;
  blocks: PrinterBlock[];
  // A printer is on its card, ready to add or to refuse.
  canAdd: boolean;
  // The printer on the card was found on the network and can be kept
  // connected: the panel offers its own access-code field, whose value goes
  // with Add to the app and never into the chat.
  accessCode?: boolean;
  // The facts the model's instructions state (printerInstructions.ts).
  context?: PrinterContext;
}

export interface PrinterContext {
  // Add: every printer the panel can set up, as [catalogId, brand and model,
  // build volume], and what is on the network now.
  printers?: [string, string, string][];
  network?: { name: string; serial: string }[];
  // Change: the printer as it is now.
  printer?: {
    name: string;
    model: string;
    nozzle: number;
    nozzles: number[];
    spools: PrinterSpoolInfo[];
    connected: boolean;
  };
"}

