import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';
import { nativeTransport } from './bridge/client';
import { applyAppearance, applyStaticTokens } from './tokens';
import './styles.css';

applyStaticTokens();
applyAppearance('light');

// A throwaway, setup-only host (e.g. embedded in the Add a printer dialog)
// loads this same page with ?embedded=1 so it renders only the setup
// sub-component instead of the full conversation chrome. See App.tsx.
const query = new URLSearchParams(window.location.search);
const embedded = query.get('embedded') === '1';
// The printer panel on Home loads the same page with ?panel=printer: the same
// thread and composer, with the printer session's card pinned above them
// instead of the project's setup card. See App.tsx.
const panel = query.get('panel') === 'printer';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App getTransport={nativeTransport} embedded={embedded} printerPanel={panel} />
  </StrictMode>,
);

const photo: AttachmentInfo = {
  id: 'a-1',
  name: 'IMG_2041.jpg',
  kind: 'image',
  state: 'staged',
  sizeBytes: 402_110,
} as AttachmentInfo;

function panel(
  state: PrinterSessionPayload,
  messages: Message[],
  attachments: AttachmentInfo[] = [],
  activities: ToolActivityInfo[] = [],
) {
  return renderToStaticMarkup(
    <div className="app app--printer">
      <div className="chat-content">
        <header className="chat-header printer-header">
          <button type="button" className="icon-button" aria-label="Back to printers">
            ‹
          </button>
          <h1>Printers</h1>
          <button type="button" className="printer-manual-link">
            Set it up myself
          </button>
        </header>
        <div className="pinned-setup">
          <PrinterPinnedCard session={state} />
        </div>
        <MessageList
          messages={messages}
          attachments={attachments}
          streamingMessageId={null}
          toolActivities={activities}
          renderActivity={(activity) => <PrinterChangeCard activity={activity} onDecision={noop} />}
          builds={[]}
          exportedCopies={[]}
          physicalPrints={[]}
          changes={[]}
          printerBlocks={state.blocks}
          onPrinterAction={noop}
          answeredState={false}
          onRetry={noop}
          onToolDecision={noop}
          onToolCancel={noop}
        />
        {state.accessCode && <PrinterAccessCode value="" onChange={noop} />}
        <PrinterChipRow canAdd={state.canAdd} disabled={false} onAdd={noop} onReject={noop} />
        <Composer
          disabled={false}
          placeholder={placeholder(state)}
          photoButton
          streaming={false}
          attachments={attachments}
          onSend={noop}
          onStop={noop}
          onAttachFiles={noop}
          onRemoveAttachment={noop}
        />
      </div>
    </div>,
  );
}


