using namespace Slic3r::GUI::JusPrin;
using namespace Slic3r::GUI::JusPrin::PrinterSetup;
using Catch::Matchers::ContainsSubstring;
using nlohmann::json;

namespace {

CatalogPrinter mini()
{
    CatalogPrinter printer;
    printer.id              = "BBL/Bambu Lab A1 mini";
    printer.vendor_id       = "BBL";
    printer.vendor_name     = "Bambu Lab";
    printer.model_id        = "Bambu Lab A1 mini";
    printer.model_name      = "A1 mini";
    printer.device_model_id = "N1";
    printer.build_volume    = "180 × 180 × 180 mm";
    printer.default_plate   = "Textured PEI Plate";
    printer.nozzles         = {0.2, 0.4, 0.6, 0.8};
    printer.filaments       = {"Bambu PLA Basic @BBL A1M 0.2 nozzle", "Bambu PLA Basic @BBL A1M", "Bambu PLA Basic @BBL A1M",
                               "Bambu PLA Basic @BBL A1M"};
    return printer;
}

// No plate in its profile, like most printers, and a nozzle list without 0.4
// on one of them.
CatalogPrinter mk3s()
{
    CatalogPrinter printer;
    printer.id           = "Prusa/Prusa MK3S";
    printer.vendor_id    = "Prusa";
    printer.vendor_name  = "Prusa";
    printer.model_id     = "Prusa MK3S";
    printer.model_name   = "MK3S";
    printer.build_volume = "250 × 210 × 210 mm";
    printer.nozzles      = {0.25, 0.4, 0.6, 0.8};
    printer.filaments    = {"Prusa Generic PLA", "Prusa Generic PLA", "Prusa Generic PLA", "Prusa Generic PLA"};
    return printer;
}

CatalogPrinter ender(const std::string& name)
{
    CatalogPrinter printer;
    printer.id           = "Creality/Creality " + name;
    printer.vendor_id    = "Creality";
    printer.vendor_name  = "Creality";
    printer.model_id     = "Creality " + name;
    printer.model_name   = name;
    printer.build_volume = "220 × 220 × 250 mm";
    printer.nozzles      = {0.6, 0.8};
    printer.filaments    = {"Creality Generic PLA", ""};
    return printer;
}

class FakeBackend final : public IPrinterBackend
{
public:
    std::vector<CatalogPrinter>    catalogue{mini(), mk3s(), ender("Ender-3 V2"), ender("Ender-3 S1"), ender("Ender-3 Pro"),
                                          ender("Ender-3 Max")};
    std::vector<DiscoveredPrinter> network;
    std::vector<SavedPrinter>      saved;
    std::string                    refusal;

    std::vector<AddPrinterRequest>    added;
    std::vector<ChangePrinterRequest> changed;
    int                               manual_setups{0};
    std::vector<std::string>          settings_opened;

    const std::vector<CatalogPrinter>& catalog() const override { return catalogue; }
    std::vector<DiscoveredPrinter>     network_printers() const override { return network; }
    std::vector<SavedPrinter>          saved_printers() const override { return saved; }

    std::string add_printer(const AddPrinterRequest& request, SavedPrinter& result) override
    {
        added.push_back(request);
        if (!refusal.empty())
            return refusal;
        result.name = request.name;
        return {};
    }
    // Saves the change into `saved`, as the Orca backend does.
    std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& result) override
    {
        changed.push_back(request);
        if (!refusal.empty())
            return refusal;
        for (SavedPrinter& printer : saved)
            if (printer.name == request.name) {
                if (request.nozzle)
                    printer.nozzle = *request.nozzle;
                if (request.spools)
                    printer.spools = *request.spools;
                result = printer;
            }
        return {};
    }
    ManualPrinterResult manual_result;
    PrinterConnectionInfo connection_info;
    std::vector<std::string> connection_names;
    std::string connection_code;
    std::string connection_error;
    PrinterConnectionInfo connection(const std::string&) override { return connection_info; }
    std::string connect_printer(const std::string& name, const std::string&, const std::string& code) override
    {
        connection_names.push_back(name);
        connection_code = code;
        return connection_error;
    }
    ManualPrinterResult run_manual_setup() override { ++manual_setups; return manual_result; }
    void open_printer_settings(const std::string& name) override { settings_opened.push_back(name); }
};

class RecordingPanel final : public IConversationHost
{
public:
    std::vector<std::string> notes;
    std::vector<std::string> openings;
    int                      turns{0};
    int                      states{0};
    int                      profiles{0};
    int                      closes{0};
    int                      refreshes{0};

    std::string post_note(const std::string& text) override
    {
        notes.push_back(text);
        return "note-" + std::to_string(notes.size());
    }
    std::string post_opening(const std::string& text) override
    {
        openings.push_back(text);
        return "opening-" + std::to_string(openings.size());
    }
    void start_turn() override { ++turns; }
    void session_changed() override { ++states; }
    void profile_changed() override { ++profiles; }
    // The receipt a close_panel() call carried, or unset for a plain close.
    std::optional<PinnedFacts> last_closed_with;
    void close_panel(const PinnedFacts* added) override
    {
        ++closes;
        last_closed_with = added != nullptr ? std::optional<PinnedFacts>(*added) : std::nullopt;
    }
    // The last receipt an Add passed, or unset for a refresh with none.
    std::optional<PinnedFacts> last_added_printer;
    void printers_changed(const PinnedFacts* added) override
    {
        ++refreshes;
        last_added_printer = added != nullptr ? std::optional<PinnedFacts>(*added) : std::nullopt;
    }
};

Agent::ToolActivity call(const char* tool, const json& arguments, const std::string& message = "m-1")
{
    Agent::ToolActivity activity;
    activity.tool           = tool;
        message('m1', 'assistant',
          'This is the Bambu Lab A1 mini. Tell me what changed on it, or ask anything about it: nozzle, plate, spools, connection. A photo of the part works too.'),
        message('m2', 'user', 'i put a 0.6 nozzle on it'),
        message('m3', 'assistant', ''),
      ],
      [],
      [changeActivity('pending')],
    ),
  },
  {
    name: 'Change · a nozzle swapped',
    note: 'the changed fact is the only red thing in the card; Undo is the app’s',
    body: panel(
      session({
        mode: 'change',
        facts: facts('Bambu Lab A1 mini', [0.6, 'changed'], 'Textured PEI Plate', { ams: 'AMS lite', spools: loaded.slice(0, 2) }),
        blocks: [
          { id: 'undo', seq: 1, afterMessageId: 'm3', kind: 'undo', changed: { nozzle: { before: 0.4, after: 0.6 } } },
        ],
      }),
      [
        message('m1', 'assistant',
          'This is the Bambu Lab A1 mini. Tell me what changed on it, or ask anything about it: nozzle, plate, spools, connection. A photo of the part works too.'),
        message('m2', 'user', 'i put a 0.6 nozzle on it'),
        message('m3', 'assistant', ''),
        message('m4', 'assistant', "Done — it's on the 0.6 mm nozzle now. You can print thicker layers with it."),
      ],
      [],
      [changeActivity('succeeded')],
    ),
  },
];

describe('printer panel preview', () => {
  it('writes a page showing every state at the printers column width', () => {
    const out = process.env.PREVIEW_OUT;
    if (!out) return;

    const css = readFileSync(resolve(__dirname, '../styles.css'), 'utf8');
    applyStaticTokens();
    const staticVars = document.documentElement.style.cssText;
    const semantic = (tokens as { semantic: Record<string, Record<string, Record<string, string>>> }).semantic;
    const varsFor = (mode: string) =>
      Object.entries(semantic[mode])
        .flatMap(([group, values]) => Object.entries(values).map(([name, value]) => `--${group}-${name}: ${value};`))
        .join('\n  ');

    const width = (tokens as { component: { printerCard: { columnWidth: number } } }).component.printerCard.columnWidth;
    const panels = (mode: string) =>
      [...cases(), ...[
        { name: 'Printer added', connection: null },
        { name: 'Connect later', connection: { name: 'Garage A1 mini', provider: 'bambu', state: 'not_configured' as const,
          message: '', deviceId: '', candidates: [{ id: 'example', name: 'A1 mini', address: '192.168.1.20' }] } },
        { name: 'Connection failed', connection: { name: 'Garage A1 mini', provider: 'bambu', state: 'failed' as const,
          message: 'The printer did not respond. Check that it is on the network and try again.', deviceId: 'example',
          candidates: [{ id: 'example', name: 'A1 mini', address: '192.168.1.20' }] } },
        { name: 'Print host', connection: { name: 'Workshop printer', provider: 'host', state: 'not_configured' as const,
          message: '', deviceId: '', candidates: [], address: '', hostType: 'moonraker' } },
      ].map(({ name, connection }) => ({ name, note: 'Optional connection, independent of the AI assistant',
        body: renderToStaticMarkup(<div className="app app--printer"><PrinterConnection
          session={session({ added: [{ name: connection?.name ?? 'Garage A1 mini', model: 'A1 mini' }], connection })}
          onAction={noop} /></div>),
      }))]
        .map((entry) => `<figure>
  <figcaption><b>${entry.name}</b> — ${entry.note}</figcaption>
  <div class="column ${mode}">${entry.body}</div>
</figure>`)
        .join('\n');

    writeFileSync(out, `<!doctype html><meta charset="utf-8"><title>Printer panel</title>
<style>
:root { ${varsFor('light')} ${staticVars} }
${css}
.dark { ${varsFor('dark')} }
body { background: #f2f2f2; font-family: system-ui, sans-serif; padding: 16px; margin: 0; }
.grid { display: flex; flex-wrap: wrap; gap: 16px; align-items: flex-start; }
figure { margin: 0; }
figcaption { font-size: 12px; margin-bottom: 6px; color: #333; max-width: ${width}px; }
/* Home's printers column, which this panel takes over. */
.column { width: ${width}px; height: 620px; border: 1px solid #bbb; background: var(--surface-subtle); overflow: hidden; }
.column.dark { color: var(--text-primary); }
.column .app { height: 100%; }
h2 { font: 600 14px system-ui, sans-serif; margin: 20px 0 10px; }
</style>
<h2>Light</h2>
<div class="grid">
${panels('light')}
</div>
<h2>Dark</h2>
<div class="grid">
${panels('dark')}
</div>
`);
  });
});

