import { act, fireEvent, render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import { PrinterConnection } from './PrinterConnection';
import type { PrinterConnectionInfo, PrinterSessionPayload } from '../bridge/protocol';

const session = (connection?: Partial<PrinterConnectionInfo>): PrinterSessionPayload => ({
  mode: 'connect', canAdd: false, blocks: [], facts: {} as PrinterSessionPayload['facts'],
  added: [{ name: 'Garage', model: 'A1 mini' }],
  connection: connection ? { name: 'Garage', provider: 'bambu', state: 'not_configured', message: '', deviceId: '',
    candidates: [{ id: 'serial', name: 'A1 mini', address: '192.168.1.2' }], ...connection } : null,
});

describe('printer addition and connection', () => {
  it('confirms the save and makes skipping connection explicit', () => {
    const onAction = vi.fn();
    render(<PrinterConnection session={session()} onAction={onAction} />);
    expect(screen.getByRole('heading', { name: 'Your printer has been added' })).toHaveFocus();
    fireEvent.click(screen.getByRole('button', { name: 'Not now' }));
    expect(onAction).toHaveBeenCalledWith('close');
  });
  it('submits credentials only with a connection and clears the field', () => {
    const onAction = vi.fn();
    render(<PrinterConnection session={session({})} onAction={onAction} />);
    const input = screen.getByLabelText('LAN access code');
    fireEvent.change(input, { target: { value: 'secretcode' } });
    fireEvent.click(screen.getByRole('button', { name: 'Connect' }));
    expect(onAction).toHaveBeenCalledWith('connection_start', '', { deviceId: 'serial', accessCode: 'secretcode' });
    expect(input).toHaveValue('');
  });
  it('retains the saved receipt when the connection fails', () => {
    render(<PrinterConnection session={session({ state: 'failed', message: 'Check the access code.' })} onAction={vi.fn()} />);
    expect(screen.getByRole('alert')).toHaveTextContent('Check the access code.');
    expect(screen.getByRole('heading', { name: 'Your printer has been added' })).toBeInTheDocument();
    expect(screen.queryByRole('button', { name: 'Add this printer' })).not.toBeInTheDocument();
  });
  it('polls only during an active connection and stops after unmount', () => {
    vi.useFakeTimers();
    const onAction = vi.fn();
    const view = render(<PrinterConnection session={session({ state: 'connecting' })} onAction={onAction} />);
    act(() => vi.advanceTimersByTime(1000));
    expect(onAction).toHaveBeenCalledWith('connection_refresh');
    view.unmount();
    onAction.mockClear();
    act(() => vi.advanceTimersByTime(2000));
    expect(onAction).not.toHaveBeenCalled();
    vi.useRealTimers();
  });
  it('uses the host test without claiming live printer status', () => {
    render(<PrinterConnection session={session({ provider: 'host', state: 'verified' })} onAction={vi.fn()} />);
    expect(screen.getByRole('status')).toHaveTextContent('live printer status is not shown here');
    expect(screen.queryByRole('button', { name: 'Connect' })).not.toBeInTheDocument();
  });
});
import type { PrinterInfo } from '../bridge/protocol';
import { MonitorGlyph, PrinterGlyph } from './Glyphs';
import { PrinterActions, PrinterMenu } from './PrinterMenu';

// A printing printer opens into its job; every other printer stays one row.
// Giving both states the same green dot made them indistinguishable, so only
// a printing printer's dot is colored. Either way the header row ends in the
// printer's actions menu.
export function PrinterCard({
  printer,
  otherNames,
  actions,
  onLaunchMonitor,
  highlighted,
}: {
  printer: PrinterInfo;
  otherNames: string[];
  actions: PrinterActions;
  onLaunchMonitor: (id: string) => void;
  // The printer a receipt just named: the card's own CSS animation draws
  // attention to it once and ends on its own -- no timer either side manages.
  highlighted?: boolean;
}) {
  const printing = printer.state === 'printing';
  const name = (
    <span className="printer-name-row">
      <PrinterGlyph />
      <span className="printer-name">{printer.name}</span>
    </span>
  );
  // A LAN-only device offers none of the actions; a menu of disabled rows
  // would be a button that does nothing, so it has none.
  const hasActions = printer.canOpenSettings || printer.canRename || printer.canRemove;
  const end = (
    <span className="printer-head-end">
      <span className={printing ? 'status-dot printing' : 'status-dot'} aria-hidden="true" />
      {hasActions && <PrinterMenu printer={printer} otherNames={otherNames} actions={actions} />}
    </span>
  );
  const cardClass = (base: string) => (highlighted ? `${base} printer-card-added` : base);
  if (!printing) {
    return (
      <div className={cardClass('printer-card')}>
        <div className="printer-head">{name}{end}</div>
        {printer.connectionText && <div className="printer-detail">{printer.connectionText}</div>}
        {printer.kind === 'named' && actions.onConnect && <button type="button" className="button-secondary" onClick={() => actions.onConnect?.(printer.id)}>Connect printer</button>}
      </div>
    );
  }
  return (
    <div className={cardClass('printer-card')}>
      <div className="printer-head">
        {name}
        {end}
      </div>
      {printer.statusText && <div className="printer-job">{printer.statusText}</div>}
      {printer.progressPercent !== undefined && (
        <div
          className="printer-progress"
          role="progressbar"
          aria-valuenow={Math.round(printer.progressPercent)}
          aria-valuemin={0}
          aria-valuemax={100}
        >
          <span style={{ width: `${Math.max(0, Math.min(100, printer.progressPercent))}%` }} />
        </div>
      )}
      {printer.connectionText && <div className="printer-detail">{printer.connectionText}</div>}
      {printer.nozzleText && <div className="printer-detail">{printer.nozzleText}</div>}
      {printer.spools.length > 0 && (
        <div className="printer-spools">
          {printer.materialLabel && <span className="printer-material">{printer.materialLabel}</span>}
          {printer.spools.map((spool, index) => (
            // The border is what keeps a black spool visible on the dark card
            // and a white one on the light card.
            <span
              key={`${spool.colour}-${index}`}
              className="spool-swatch"
              style={{ background: spool.colour }}
            />
          ))}
        </div>
      )}
      {printer.canLaunchMonitor && (
        <button type="button" className="button-secondary launch-monitor" onClick={() => onLaunchMonitor(printer.id)}>
          <MonitorGlyph />
          Launch monitor
        </button>
      )}
    </div>
  );
}

