    // --- The worked examples, live (--printer-live) ------------------------
    //
    // The handoff's worked examples through the real panel: its own session,
    // the live model, the Orca backend. Words and taps go in as the page would
    // send them; each exchange is printed for reading, and what can be checked
    // mechanically is.

    struct LiveStep
    {
        std::string            label;
        std::function<void()>  act;   // opens a session, or sends words or a tap
        std::function<bool()>  ready; // when the exchange has settled
        std::function<void()>  check; // then
    };
    std::deque<LiveStep> m_live_steps;
    std::size_t          m_live_printed{0};
    std::size_t          m_live_messages_before{0};
    std::string          m_live_printer;

    PrinterSetup::PrinterPanel* live_panel() const
    {
        ShellController* shell = installed_shell();
        return shell == nullptr ? nullptr : shell->printer_panel();
    }

    void live_send(const std::string& type, const nlohmann::json& payload)
    {
        static int next = 0;
        live_panel()->host()->on_page_message(nlohmann::json{{"protocol", Agent::Protocol::kName},
                                                             {"version", Agent::Protocol::kVersion},
                                                             {"id", "live-" + std::to_string(++next)},
                                                             {"type", type},
                                                             {"payload", payload}}
                                                  .dump());
    }

    // Clicks the button on the panel's own page that carries these words, as
    // the person would, so what the page sends with the tap is what the app
    // receives.

const CatalogPrinter* PrinterConversation::catalog_entry(const std::string& id) const
{
    const std::vector<CatalogPrinter>& catalog = m_backend.catalog();
    const auto entry = std::find_if(catalog.begin(), catalog.end(), [&id](const CatalogPrinter& printer) { return printer.id == id; });
    return entry == catalog.end() ? nullptr : &*entry;
}

const CatalogPrinter* PrinterConversation::model_of(const DiscoveredPrinter& device) const
{
    if (device.device_model_id.empty())
        return nullptr;
    const std::vector<CatalogPrinter>& catalog = m_backend.catalog();
    const auto entry = std::find_if(catalog.begin(), catalog.end(), [&device](const CatalogPrinter& printer) {
        return printer.device_model_id == device.device_model_id;
    });
    return entry == catalog.end() ? nullptr : &*entry;
}

json* PrinterConversation::block(const std::string& id)
{
    for (json& entry : m_blocks)
        if (entry.value("id", std::string()) == id)
            return &entry;
    return nullptr;
}

double PrinterConversation::assumed_nozzle(const CatalogPrinter& printer) const
{
    if (printer.nozzles.empty() || ships(printer.nozzles, 0.4))
        return 0.4;
    return printer.nozzles.front();
}

json PrinterConversation::identified_json(const CatalogPrinter& printer, double nozzle) const
